SELECT 
FROM service_item
WHERE 1=1

    AND category_id = #{categoryId}


    AND service_name LIKE CONCAT('%', #{serviceName}, '%')


    AND service_code = #{serviceCode}


    AND status = #{status}

ORDER BY sort ASC, sales_count DESC, create_time DESC

SELECT 
FROM service_item
WHERE 1=1

    AND category_id = #{service.categoryId}


    AND service_name LIKE CONCAT('%', #{service.serviceName}, '%')


    AND status = #{service.status}

ORDER BY sort ASC, sales_count DESC, create_time DESC
LIMIT #{offset}, #{pageSize}

SELECT COUNT(*)
FROM service_item
WHERE 1=1

    AND category_id = #{categoryId}


    AND service_name LIKE CONCAT('%', #{serviceName}, '%')


    AND status = #{status}
